const SPHINX = "sphinx";

// A card's type is its monster alone — variants of the same monster
// (e.g. Undead Warrior ranks) all count as one type.
const typeOf = (card: Card): string => card.monster;

const distinctTypes = (army: Card[]): Set<string> => new Set(army.map(typeOf));

const containsSphinx = (army: Card[]): boolean =>
  distinctTypes(army).has(SPHINX);

const countNonSphinxTypes = (army: Card[]): number => {
  const types = distinctTypes(army);
  types.delete(SPHINX);
  return types.size;
};
